export interface SystemFailureResult { alternativeProcess: string; notificationTargets: string[]; dataRecoveryPlan: string; estimatedRecoveryTime: number }

export interface ViewPermissionResult { canView: boolean; viewLevel: string; allowedFields: string[] }

export interface FallbackResult { fallbackMethod: string; emergencyContactList: string[]; paperFormUrl: string; syncRequired: boolean }

export interface ContinuityResult { continuityPlan: string; temporaryRoutes: string[]; rollbackProcedure: string; communicationPlan: string }

export interface ValidationResult { isValid: boolean; errors: string[]; warnings: string[] }

function calculateRecoveryTime(failureType: string): number {
  if (failureType === "database_connection" || failureType === "database_connection_lost") {
    return 8;
  } else if (failureType === "api_timeout") {
    return 4;
  } else if (failureType === "network_slow") {
    return 2;
  } else {
    return 6;
  }
}

export function handleSystemFailureAlternativeProcess(
  systemStatus: string,
  failureType: string,
  documentType: string,
  urgencyLevel: number
): SystemFailureResult {
  // システム状況の確認
  if (!systemStatus || systemStatus === null || systemStatus === "") {
    throw new Error("システム状況を確認できません。情報システム課に連絡してください。");
  }

  // 緊急度の範囲チェック（1-10の範囲外の場合はクランプ）
  let clampedUrgencyLevel = urgencyLevel;
  if (urgencyLevel < 1) {
    clampedUrgencyLevel = 1;
  } else if (urgencyLevel > 10) {
    clampedUrgencyLevel = 10;
  }

  // 代替処理方法の決定
  let alternativeProcess: string;
  if (systemStatus === "critical_failure") {
    alternativeProcess = "full_paper_mode";
  } else if (systemStatus === "partial_failure") {
    alternativeProcess = "manual_hybrid_mode";
  } else {
    alternativeProcess = "temporary_workaround";
  }

  // 通知対象者の決定
  let notificationTargets: string[];
  if (clampedUrgencyLevel >= 8) {
    notificationTargets = ["all_staff", "management", "it_support"];
  } else {
    notificationTargets = ["relevant_staff", "it_support"];
  }

  // データ復旧計画の設定
  const dataRecoveryPlan = "sync_paper_to_electronic_after_recovery";

  // 復旧予定時間の計算
  const estimatedRecoveryTime = calculateRecoveryTime(failureType);

  return {
    alternativeProcess,
    notificationTargets,
    dataRecoveryPlan,
    estimatedRecoveryTime
  };
}

